SELECT 
FROM twelve_exchange_order
WHERE id = #{orderId}
AND tenant_id = #{tenantId}

SELECT 
FROM twelve_exchange_order
WHERE (owner_a_id = #{userId} OR owner_b_id = #{userId})
AND tenant_id = #{tenantId}

    AND status IN
    #{st}

ORDER BY create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM twelve_exchange_order
WHERE (owner_a_id = #{userId} OR owner_b_id = #{userId})
AND tenant_id = #{tenantId}

    AND status IN
    #{st}

SELECT 
FROM twelve_exchange_order
WHERE status IN ('created', 'delivering')
  AND a_delivered_time IS NULL AND b_delivered_time IS NULL
  AND create_time <= #{threshold}

LIMIT #{limit}

SELECT 
FROM twelve_exchange_order
WHERE status = 'pending_confirm'
  AND GREATEST(a_delivered_time, b_delivered_time) <= #{threshold}

LIMIT #{limit}
